/// <summary>Query extensions: including the whole cascade graph of an entity with a single method call (the read-side counterpart of the graph save - combine it with Where or GetByIdAsync to bound what is fetched), and fetching a single entity by its key.</summary>
/// <remarks>
/// The Include tree of each entity is built once and shared by every query, so it must stay unmodified after construction.
/// </remarks>
public static class SqlQueryExtensions
{
    /// <summary>Includes the cascade graph of IdentityItemEntity (it has no child-direction navigation, so the query is returned unchanged).</summary>
    public static SqlQuery<IdentityItemEntity> IncludeGraph(this SqlQuery<IdentityItemEntity> query) => query;

    /// <summary>Fetches the single entity with the given key - the same key the repository contract's GetByIdAsync takes - and returns null when no row matches.</summary>
    /// <remarks>Combine it with Include or IncludeGraph to fetch that entity together with its graph in one call.</remarks>
    public static Task<IdentityItemEntity?> GetByIdAsync(
        this SqlQuery<IdentityItemEntity> query,
        int id,
        CancellationToken cancellationToken = default
    ) => query.Where(entity => entity.ItemId == id).FirstOrDefaultAsync(cancellationToken);

    /// <summary>Fetches the single entity with the given key, keeping the Include chain written just before it (returns null when no row matches).</summary>
    public static Task<IdentityItemEntity?> GetByIdAsync<TProperty>(
        this IncludableSqlQuery<IdentityItemEntity, TProperty> query,
        int id,
        CancellationToken cancellationToken = default
    ) => query.Where(entity => entity.ItemId == id).FirstOrDefaultAsync(cancellationToken);
}

/// <summary>Base of every generated HTTP client repository, and the extension point for them. Members added to a partial declaration of this class are available to every entity client.</summary>
/// <remarks>The HTTP change source the sync engine uses is not one of them: it lives in the fixed runtime, which cannot name a generated type, so it derives from <see cref="HttpRemoteRepositoryCore{TEntity, TKey}"/> directly and members added here do not reach it.</remarks>
/// <typeparam name="TEntity">The entity type.</typeparam>
/// <typeparam name="TKey">The primary key type.</typeparam>
public abstract partial class HttpRemoteRepository<TEntity, TKey>
    : HttpRemoteRepositoryCore<TEntity, TKey>
    where TEntity : EntityBaseCore, new()
{
    /// <summary>Initializes a new instance with the HTTP client and the entity route (for example "Order").</summary>
    protected HttpRemoteRepository(HttpClient httpClient, string entityRoute)
        : base(httpClient, entityRoute) { }
}

